package com.chatsystem.user.controller.social;import com.chatsystem.shared.service.SocialService;import javafx.fxml.FXML;import javafx.scene.control.*;public final class AddFriendDialogController{private final SocialService social;@FXML private TextField targetField;@FXML private Label feedbackLabel;public AddFriendDialogController(SocialService s){social=s;}@FXML private void submit(){try{var r=social.sendRequest(Long.parseLong(targetField.getText().strip()));feedbackLabel.setText(r.isSuccess()?"Friend request sent":r.errors().get(0).message());}catch(RuntimeException e){feedbackLabel.setText("Enter a valid account ID");}}@FXML private void cancel(){targetField.getScene().getWindow().hide();}}
